function parseDateTime(date,time='23:59'){if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date||''))||!/^\d{2}:\d{2}$/.test(String(time||'')))return null;const d=new Date(`${date}T${time}:00`);return Number.isNaN(d.getTime())?null:d}
function isoOrNull(value){if(!value)return null;const d=new Date(value);return Number.isNaN(d.getTime())?null:d.toISOString()}
