function formatDayTime(value){const d=safeTime(value);if(!d)return 'Date unavailable';const today=startOfDay(nowDate()),diff=Math.round((startOfDay(d)-today)/DAY);const day=diff===0?'Today':diff===1?'Tomorrow':d.toLocaleDateString([], {month:'short',day:'numeric'});return `${day} · ${formatClock(d)}`}
function relativeTime(value){const d=safeTime(value);if(!d)return 'Date unavailable';const ms=d-nowDate(),abs=Math.abs(ms),mins=Math.max(1,Math.round(abs/MINUTE));if(ms<0)return mins<1440?`Overdue by ${mins<60?mins+' min':Math.round(mins/60)+' hr'}`:`Overdue by ${Math.round(mins/1440)} day(s)`;if(mins<60)return `Due in ${mins} min`;if(mins<1440)return `Due in ${Math.round(mins/60)} hr`;return `Due in ${Math.ceil(mins/1440)} day(s)`}

function priorityRoot(){
  const root=workspaceState.dashboardPriority&&typeof workspaceState.dashboardPriority==='object'?workspaceState.dashboardPriority:{};
  workspaceState.dashboardPriorityVersion=VERSION;
  workspaceState.dashboardLayoutMode=workspaceState.dashboardLayoutMode==='detailed'?'detailed':'compact';
  workspaceState.dashboardPriority={version:VERSION,itemState:root.itemState||{},assignmentDueDates:root.assignmentDueDates||{},firstSeen:root.firstSeen||{}};
  workspaceState.customAssignments=Array.isArray(workspaceState.customAssignments)?workspaceState.customAssignments:[];
  const today=startOfDay(nowDate()),offsets={eds6001:6,eds6019:16,ece6156:30};
  Object.keys(assignmentCatalog).forEach(id=>{if(!workspaceState.dashboardPriority.assignmentDueDates[id]){const due=addDays(today,offsets[id]||21);due.setHours(23,59,0,0);workspaceState.dashboardPriority.assignmentDueDates[id]=due.toISOString()}});
  (workspaceState.miscTasks||[]).forEach((task,index)=>{if(!task.id)task.id=`task-${Date.now()}-${index}-${hash(task.title)}`;if(task.estimatedMinutes==null)task.estimatedMinutes=30});
  workspaceState.customAssignments.forEach((task,index)=>{if(!task.id)task.id=`custom-assignment-${Date.now()}-${index}-${hash(task.title)}`;task.done=Boolean(task.done)});
  return workspaceState.dashboardPriority;
}
const priorityState=priorityRoot();
function controlFor(id){return priorityState.itemState[id]||(priorityState.itemState[id]={status:'active',completedAt:null,snoozeUntil:null,pinned:false,manualPriority:'auto',dismissedAt:null,scheduledEventId:null,updatedAt:new Date().toISOString()})}
function firstSeen(id){return priorityState.firstSeen[id]||(priorityState.firstSeen[id]=new Date().toISOString())}
function item(data){
  const meta=TYPE_META[data.sourceType]||TYPE_META.personal,control=controlFor(data.id);
  const dueAt=isoOrNull(data.dueAt),startAt=isoOrNull(data.startAt);
  return {id:data.id,sourceType:data.sourceType,sourceId:data.sourceId??null,courseCode:data.courseCode||'',title:clean(data.title),description:clean(data.description),dueAt,startAt,dateInvalid:Boolean((data.dueAt&&!dueAt)||(data.startAt&&!startAt)),estimatedMinutes:Number(data.estimatedMinutes)||30,importance:data.importance||'normal',status:control.status||data.status||'active',createdAt:data.createdAt||firstSeen(data.id),updatedAt:control.updatedAt||data.updatedAt||firstSeen(data.id),completedAt:control.completedAt||data.completedAt||null,snoozeUntil:control.snoozeUntil||null,pinned:Boolean(control.pinned),manualPriority:control.manualPriority||'auto',actionType:data.actionType||'open',actionTarget:data.actionTarget??data.sourceId??null,reason:'',score:0,icon:meta.icon,tone:meta.tone,typeLabel:meta.label,canComplete:data.canComplete!==false,sourceCompleted:Boolean(data.sourceCompleted)};
}
function courseWeight(code){return CORE_COURSES.has(code)?5:code?2:0}
function courseLectures(code){return [...(courseCatalog[code]?.lectures||[]),...(workspaceState.customLectures?.[code]||[])]}
function parseMailDate(text){const match=String(text||'').match(/^([A-Za-z]{3})\s+(\d{1,2})\s*·\s*(\d{1,2}):(\d{2})/);if(!match)return null;const month=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].indexOf(match[1]);if(month<0)return null;const now=nowDate(),d=new Date(now.getFullYear(),month,Number(match[2]),Number(match[3]),Number(match[4]));if(d-now>31*DAY)d.setFullYear(d.getFullYear()-1);return d}
function recurringUntil(event){return parseDateTime(event.until,'23:59')||(event.id==='class-cui6078'?new Date('2026-12-12T23:59:00'):new Date('2026-12-05T23:59:00'))}
function eventOccurrences(event,from,to){
  const first=parseDateTime(event.date,event.time);if(!first)return [];
  if(!event.recurring)return first>=from&&first<=to?[{...event,occurrenceStart:first}]:[];
  const until=recurringUntil(event),result=[];for(let day=startOfDay(from);day<=to;day=addDays(day,1)){if(day.getDay()!==first.getDay())continue;const start=parseDateTime(dateKey(day),event.time);if(start>=first&&start<=until&&start>=from&&start<=to)result.push({...event,occurrenceStart:start})}return result;
}
function allOccurrences(from,to){return (workspaceState.events||[]).flatMap(e=>eventOccurrences(e,from,to)).sort((a,b)=>a.occurrenceStart-b.occurrenceStart)}
function sourceIsComplete(sourceType,sourceId,courseCode){
  if(sourceType==='assignment'){if(String(sourceId).startsWith('custom:'))return Boolean(workspaceState.customAssignments.find(x=>x.id===String(sourceId).slice(7))?.done);const a=workspaceState.assignments[sourceId];return Boolean(a?.tasks?.length&&a.tasks.every(Boolean))}
  if(sourceType==='generated'){const a=(workspaceState.generatedAssignments||[]).find(x=>x.id===sourceId);return Boolean(a?.tasks?.length&&(a.done||[]).length>=a.tasks.length&&a.tasks.every((_,i)=>a.done?.[i]))}
  if(sourceType==='paper')return workspaceState.papers.find(x=>x.id===sourceId)?.status==='Completed';
  if(sourceType==='personal')return Boolean((workspaceState.miscTasks||[]).find(x=>x.id===sourceId)?.done);
  if(sourceType==='lecture')return Boolean(workspaceState.lectureReviewStatus?.[courseCode]?.[Number(sourceId)]);
  return false;
}
function collectPriorityItems(){
  const now=nowDate(),items=[];
  mails.forEach((mail,index)=>{const actionable=mail.tag==='Action required'||['High','Action'].includes(mail.priority);if(!actionable||!clean(mail.action)||/no (other )?action required/i.test(mail.action))return;items.push(item({id:`mail:${hash(mail.url||mail.title)}`,sourceType:'mail',sourceId:index,title:mail.title,description:mail.action,importance:mail.priority||'normal',createdAt:parseMailDate(mail.received)?.toISOString(),estimatedMinutes:15,actionTarget:index}))});
  Object.entries(assignmentCatalog).forEach(([id,a])=>items.push(item({id:`assignment:${id}`,sourceType:'assignment',sourceId:id,courseCode:a.course,title:`${a.course} · ${a.title}`,description:a.brief,dueAt:priorityState.assignmentDueDates[id],estimatedMinutes:60,importance:'high',sourceCompleted:sourceIsComplete('assignment',id)})));
  workspaceState.customAssignments.forEach(a=>items.push(item({id:`assignment:custom:${a.id}`,sourceType:'assignment',sourceId:`custom:${a.id}`,courseCode:a.course,title:`${a.course&&a.course!=='Personal'?a.course+' · ':''}${a.title}`,description:a.description||'User-created assignment',dueAt:a.dueAt,estimatedMinutes:a.estimatedMinutes||60,importance:a.priority||'high',sourceCompleted:Boolean(a.done)})));
  (workspaceState.generatedAssignments||[]).forEach(a=>items.push(item({id:`generated:${a.id}`,sourceType:'generated',sourceId:a.id,courseCode:a.course,title:`${a.course} · ${a.title}`,description:a.brief,estimatedMinutes:45,importance:'normal',sourceCompleted:sourceIsComplete('generated',a.id)})));
  Object.keys(courseCatalog).forEach(code=>{
    const lectures=courseLectures(code),insights=workspaceState.lectureInsights?.[code]||[];
    lectures.forEach((title,index)=>{const insight=insights[index];if(!insight)return;items.push(item({id:`lecture:${code}:${index}`,sourceType:'lecture',sourceId:index,courseCode:code,title:`Review ${code} · ${title}`,description:insight.summary||'Review the saved lecture study pack.',estimatedMinutes:20,importance:'normal',sourceCompleted:sourceIsComplete('lecture',index,code)}));
      (insight.reminders||[]).slice(0,2).forEach(text=>items.push(item({id:`reminder:${code}:${index}:${hash(text)}`,sourceType:'reminder',sourceId:index,courseCode:code,title:`${code} lecturer reminder`,description:text,estimatedMinutes:15,importance:'normal'})));
      (insight.assignments||[]).slice(0,2).forEach(text=>items.push(item({id:`requirement:${code}:${index}:${hash(text)}`,sourceType:'requirement',sourceId:index,courseCode:code,title:`${code} possible assignment requirement`,description:text,estimatedMinutes:30,importance:'high'})));
    });
    const checked=workspaceState.courseReading?.[code]||[],titles=[...(courseCatalog[code].readings||[]),...(workspaceState.readingUploads?.[code]||[]).map(x=>x.title)];
    titles.forEach((title,index)=>items.push(item({id:`reading:${code}:${index}:${hash(title)}`,sourceType:'reading',sourceId:index,courseCode:code,title:`Read · ${title}`,description:`Course reading for ${code}`,estimatedMinutes:35,importance:'normal',sourceCompleted:Boolean(checked[index])})));
  });
  (workspaceState.papers||[]).forEach(p=>items.push(item({id:`paper:${p.id}`,sourceType:'paper',sourceId:p.id,courseCode:p.course&&p.course!=='Unlinked'?p.course:'',title:p.title,description:`${p.theme||'Research paper'} · ${p.status||'Queued'}`,estimatedMinutes:45,importance:p.status==='Priority'?'high':'normal',sourceCompleted:sourceIsComplete('paper',p.id)})));
  (workspaceState.miscTasks||[]).forEach(task=>items.push(item({id:`personal:${task.id}`,sourceType:'personal',sourceId:task.id,title:task.title,description:task.description||'Personal workspace task',dueAt:task.dueAt,estimatedMinutes:task.estimatedMinutes||30,importance:task.priority||'normal',sourceCompleted:sourceIsComplete('personal',task.id)})));
  const horizon=addDays(now,7);allOccurrences(now,horizon).forEach(event=>{const key=dateKey(event.occurrenceStart);items.push(item({id:`calendar:${event.id}:${key}`,sourceType:'calendar',sourceId:event.id,courseCode:(event.title.match(/[A-Z]{3}\d{4}/)||[])[0]||'',title:event.title,description:event.location?`Location: ${event.location}`:event.module||'Calendar event',startAt:event.occurrenceStart,estimatedMinutes:event.end?Math.max(15,(parseDateTime(key,event.end)-event.occurrenceStart)/MINUTE):60,importance:'fixed',canComplete:false}))});
  const unique=new Map();items.filter(x=>x.title).forEach(x=>{if(!unique.has(x.id))unique.set(x.id,x)});return [...unique.values()];
}
function calculatePriority(entry,now=nowDate()){
  let score=0;const factors=[];const add=(points,text)=>{score+=points;if(text)factors.push({points,text})};
  const due=safeTime(entry.dueAt);if(due){const hours=(due-now)/3600000;if(hours<0)add(35,relativeTime(due));else if(hours<=24)add(30,relativeTime(due));else if(hours<=72)add(22,relativeTime(due));else if(hours<=168)add(12,relativeTime(due));else add(4,relativeTime(due))}
  const start=safeTime(entry.startAt);if(entry.sourceType==='calendar'&&start){const hours=(start-now)/3600000;if(hours<0)return {...entry,score:0,reason:'Event already started',expired:true};if(hours<=2)add(28,`Starts in ${Math.max(1,Math.round(hours*60))} min`);else if(dateKey(start)===dateKey(now))add(18,`Scheduled today at ${formatClock(start)}`);else if(dateKey(start)===dateKey(addDays(now,1)))add(8,'Scheduled tomorrow')}
  if(entry.sourceType==='mail'){if(entry.importance==='High')add(22,'High-priority email requiring action');else if(entry.importance==='Action')add(15,'Email marked Action');else if(entry.importance==='Medium')add(8,'Medium-priority email');const mail=mails[Number(entry.sourceId)];if(mail?.unread)add(5,'Unread')}
  if(entry.sourceType==='assignment')add(18,'Formal assignment');
  if(entry.sourceType==='generated')add(18,'Class activity work plan');
  if(entry.sourceType==='reminder')add(10,'Lecturer reminder');
  if(entry.sourceType==='requirement')add(18,'Requirement detected in lecture source');
  if(entry.sourceType==='reading'||entry.sourceType==='paper')add(8,entry.sourceType==='reading'?'Required course reading':'Paper in reading queue');
  if(entry.sourceType==='lecture')add(8,'Lecture review not completed');
  if(entry.courseCode)add(courseWeight(entry.courseCode),CORE_COURSES.has(entry.courseCode)?'Core course':'Elective course');
  if(entry.importance==='high'&&!['mail','assignment','requirement'].includes(entry.sourceType))add(8,'Marked important at source');
  if(entry.pinned)add(30,'Pinned by you');
  if(entry.manualPriority==='high')add(20,'Manual High priority');else if(entry.manualPriority==='medium')add(8,'Manual Medium priority');else if(entry.manualPriority==='low')add(-10,'Manual Low priority');
  if(entry.status==='waiting')add(-15,'Waiting');
  const reason=factors.sort((a,b)=>b.points-a.points).slice(0,2).map(x=>x.text).join(' · ')||'Saved workspace item';return {...entry,score:clamp(score),reason,expired:false};
}
function evaluatedItems(options={}){
  const now=nowDate(),all=collectPriorityItems().map(x=>calculatePriority(x,now));
  all.forEach(x=>{if(x.sourceCompleted&&!x.completedAt)x.completedAt=controlFor(x.id).completedAt||'source'});
  if(options.includeHidden)return all.sort(prioritySort);
  return all.filter(x=>!x.expired&&!x.sourceCompleted&&!x.completedAt&&!x.dismissedAt&&!(x.snoozeUntil&&safeTime(x.snoozeUntil)>now)).sort(prioritySort);
}
function priorityRank(value){return {high:3,medium:2,auto:1,low:0}[value]??1}
function prioritySort(a,b){return b.score-a.score||(safeTime(a.dueAt)?.getTime()||Infinity)-(safeTime(b.dueAt)?.getTime()||Infinity)||(safeTime(a.startAt)?.getTime()||Infinity)-(safeTime(b.startAt)?.getTime()||Infinity)||priorityRank(b.manualPriority)-priorityRank(a.manualPriority)||(safeTime(b.updatedAt)?.getTime()||0)-(safeTime(a.updatedAt)?.getTime()||0)||a.title.localeCompare(b.title)}
function priorityLabel(score){return score>=75?'Urgent':score>=50?'High':score>=25?'Medium':'Low'}
function metaLine(entry){const parts=[entry.courseCode||entry.typeLabel,`${entry.estimatedMinutes} min`];if(entry.dateInvalid)parts.push('Date unavailable');else if(entry.dueAt)parts.push(formatDayTime(entry.dueAt));else if(entry.startAt)parts.push(formatDayTime(entry.startAt));return parts.filter(Boolean).join(' · ')}
function persist(render=true){try{localStorage.setItem('jingWorkspaceStateV1',JSON.stringify(workspaceState))}catch(error){toast('Browser storage is full. Your latest change could not be saved.');return false}if(render)renderDashboard();return true}

function focusCard(entry){return `<article class="priority-card priority-${entry.tone}" data-priority-id="${escapeText(entry.id)}"><div class="priority-card-main"><span class="priority-source-icon">${entry.icon}</span>${entry.canComplete?`<input class="priority-check" type="checkbox" aria-label="Complete ${escapeText(entry.title)}" onchange="completePriorityItem('${entry.id}',this.checked)">`:'<span class="priority-fixed" title="Fixed calendar event">◷</span>'}<div class="priority-copy"><div class="priority-title-line"><b>${escapeText(entry.title)}</b><span class="priority-level level-${priorityLabel(entry.score).toLowerCase()}">${priorityLabel(entry.score)} · ${entry.score}</span></div><span class="priority-meta">${escapeText(metaLine(entry))}</span><span class="priority-reason">${escapeText(entry.reason)}</span></div></div><div class="priority-actions"><button class="btn ghost priority-open" onclick="openPrioritySource('${entry.id}')">Open</button>${entry.canComplete?`<button class="mini-action compact-hide" onclick="openPrioritySnooze('${entry.id}')">Snooze</button><button class="mini-action compact-hide ${entry.pinned?'active':''}" onclick="togglePriorityPin('${entry.id}')">${entry.pinned?'Unpin':'Pin'}</button><select class="compact-hide" aria-label="Manual priority" onchange="changePriorityLevel('${entry.id}',this.value)"><option value="auto" ${entry.manualPriority==='auto'&&entry.status!=='waiting'?'selected':''}>Auto</option><option value="high" ${entry.manualPriority==='high'&&entry.status!=='waiting'?'selected':''}>High</option><option value="medium" ${entry.manualPriority==='medium'&&entry.status!=='waiting'?'selected':''}>Medium</option><option value="low" ${entry.manualPriority==='low'&&entry.status!=='waiting'?'selected':''}>Low</option><option value="waiting" ${entry.status==='waiting'?'selected':''}>Waiting</option></select><button class="mini-action compact-hide" onclick="schedulePriorityItem('${entry.id}')">Schedule</button><button class="mini-action compact-hide" onclick="dismissPriorityItem('${entry.id}')">Dismiss</button><button class="mini-action compact-more" aria-label="More actions" onclick="openPriorityActions('${entry.id}')">•••</button>`:''}</div></article>`}
function itemById(id){return collectPriorityItems().map(x=>calculatePriority(x)).find(x=>x.id===id)||null}
function applyDashboardLayout(){const compact=workspaceState.dashboardLayoutMode!=='detailed';document.body.classList.toggle('dashboard-compact',compact);document.body.classList.toggle('dashboard-detailed',!compact);const button=document.getElementById('dashboardLayoutToggle');if(button){button.textContent=compact?'Detailed':'Compact';button.title=compact?'Show every priority control and section':'Fit the Dashboard into one screen';button.setAttribute?.('aria-pressed',String(!compact))}}
toggleDashboardLayout=function(){workspaceState.dashboardLayoutMode=workspaceState.dashboardLayoutMode==='detailed'?'compact':'detailed';persist(false);applyDashboardLayout();renderDashboard();toast(workspaceState.dashboardLayoutMode==='compact'?'Compact one-screen view enabled':'Detailed Dashboard enabled')};
openPriorityActions=function(id){const entry=itemById(id);if(!entry)return;openModal(`<h2>${escapeText(entry.title)}</h2><div class="priority-action-summary"><span class="priority-level level-${priorityLabel(entry.score).toLowerCase()}">${priorityLabel(entry.score)} · ${entry.score}</span><p>${escapeText(entry.reason)}</p><span class="small">${escapeText(metaLine(entry))}</span></div><div class="priority-action-grid"><button class="btn" onclick="openPrioritySource('${entry.id}')">Open source</button><button class="btn ghost" onclick="openPrioritySnooze('${entry.id}')">Snooze</button><button class="btn ghost" onclick="togglePriorityPin('${entry.id}');closeModal()">${entry.pinned?'Unpin':'Pin'}</button><button class="btn ghost" onclick="schedulePriorityItem('${entry.id}')">Schedule</button><button class="btn ghost" onclick="dismissPriorityItem('${entry.id}');closeModal()">Dismiss from Dashboard</button></div><div class="field"><label>Manual priority</label><select class="form-select" onchange="changePriorityLevel('${entry.id}',this.value);closeModal()"><option value="auto" ${entry.manualPriority==='auto'&&entry.status!=='waiting'?'selected':''}>Auto</option><option value="high" ${entry.manualPriority==='high'?'selected':''}>High</option><option value="medium" ${entry.manualPriority==='medium'?'selected':''}>Medium</option><option value="low" ${entry.manualPriority==='low'?'selected':''}>Low</option><option value="waiting" ${entry.status==='waiting'?'selected':''}>Waiting</option></select></div>`)};
function renderDynamicFocus(active){const box=document.getElementById('dashboardFocus');if(!box)return;box.innerHTML=active.length?active.slice(0,5).map(focusCard).join(''):'<div class="empty-state compact"><b>You are clear for now.</b><div>No active item is competing for attention.</div></div>'}
function renderStats(active){
  const today=dateKey(nowDate()),all=collectPriorityItems();
  const actionableMails=all.filter(x=>x.sourceType==='mail'&&!x.sourceCompleted&&!controlFor(x.id).completedAt&&!controlFor(x.id).dismissedAt);
  const dueToday=active.filter(x=>x.dueAt&&dateKey(new Date(x.dueAt))===today).length;
  const lectures=active.filter(x=>x.sourceType==='lecture').length,papers=(workspaceState.papers||[]).filter(p=>p.status!=='Completed').length,priorityPapers=(workspaceState.papers||[]).filter(p=>p.status==='Priority').length;
  const events=allOccurrences(startOfDay(nowDate()),addDays(startOfDay(nowDate()),1)).filter(e=>dateKey(e.occurrenceStart)===today&&e.occurrenceStart>=nowDate());
  const set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};set('mailActionCount',actionableMails.length);set('sideMailCount',actionableMails.length);set('dashUnreadCount',`${gmailSnapshot.inboxUnread} unread in snapshot`);set('dashDueCount',dueToday);set('dashTaskCount',`${active.filter(x=>x.sourceType!=='calendar').length} active`);set('dashLectureCount',lectures);set('dashboardPaperCount',papers);set('dashPriorityPaperCount',`${priorityPapers} priority`);set('dashCalendarCount',events.length);set('dashNextEvent',events[0]?`Next ${formatClock(events[0].occurrenceStart)}`:'No event scheduled');
}
function renderImportantMails(){const box=document.getElementById('dashboardEmails');if(!box)return;const limit=workspaceState.dashboardLayoutMode==='detailed'?4:3,entries=evaluatedItems().filter(x=>x.sourceType==='mail').slice(0,limit);box.innerHTML=entries.length?entries.map(entry=>{const m=mails[Number(entry.sourceId)];return `<div class="dash-mail-row" onclick="openPrioritySource('${entry.id}')"><div class="sender-dot">${escapeText(m.sender.charAt(0))}</div><div class="mail-copy"><b>${escapeText(m.sender)}</b><span>${escapeText(m.title)} · ${escapeText(entry.reason)}</span></div><div class="mail-priority"><span class="priority-level level-${priorityLabel(entry.score).toLowerCase()}">${priorityLabel(entry.score)}</span><span class="dash-time">${entry.score}</span></div></div>`}).join(''):'<div class="empty-state compact">No email currently requires Dashboard action.</div>'}
function busyIntervals(date){
  const from=startOfDay(date),to=addDays(from,1);return allOccurrences(from,to).map(e=>{const start=e.occurrenceStart;let end=e.end?parseDateTime(dateKey(start),e.end):new Date(start.getTime()+60*MINUTE);if(!end||end<=start)end=addDays(end||new Date(start.getTime()+60*MINUTE),1);return {start,end,event:e}}).sort((a,b)=>a.start-b.start);
}
function findSlot(entry,date=nowDate()){
  const day=startOfDay(date),duration=Math.max(15,Math.min(180,entry.estimatedMinutes))*MINUTE,busy=busyIntervals(day);let cursor=new Date(day);cursor.setHours(8,0,0,0);if(dateKey(date)===dateKey(nowDate())&&cursor<nowDate()){cursor=new Date(Math.ceil(nowDate().getTime()/(15*MINUTE))*15*MINUTE)}const limit=new Date(day);limit.setHours(22,0,0,0);
  for(const interval of busy){if(interval.end<=cursor)continue;if(cursor.getTime()+duration<=interval.start)return {start:cursor,end:new Date(cursor.getTime()+duration)};if(interval.end>cursor)cursor=new Date(Math.ceil(interval.end.getTime()/(15*MINUTE))*15*MINUTE);if(cursor>=limit)break}return cursor.getTime()+duration<=limit?{start:cursor,end:new Date(cursor.getTime()+duration)}:null;
}
function todayAgenda(active){
  const today=startOfDay(nowDate()),tomorrow=addDays(today,1),events=allOccurrences(today,tomorrow).filter(e=>dateKey(e.occurrenceStart)===dateKey(today));
  const scheduledIds=new Set(events.map(e=>e.priorityItemId).filter(Boolean)),suggestions=[];for(const entry of active.filter(x=>x.canComplete)){if(scheduledIds.has(entry.id))continue;const slot=findSlot(entry,today);if(slot){suggestions.push({entry,slot});if(suggestions.length>=2)break}}
  return {events,suggestions};
}
function renderAgenda(active){const box=document.getElementById('dashboardAgenda');if(!box)return;let {events,suggestions}=todayAgenda(active);if(workspaceState.dashboardLayoutMode!=='detailed'){events=events.slice(0,5);suggestions=suggestions.slice(0,Math.max(0,5-events.length))}const eventHtml=events.map(e=>`<div class="agenda-row ${e.module==='Focus'?'focus-block':''}" onclick="${e.priorityItemId?`schedulePriorityItem('${e.priorityItemId}')`:`openEvent('${e.id}')`}"><div><b>${escapeText(formatClock(e.occurrenceStart))}${e.end?'–'+escapeText(e.end):''}</b><span>${escapeText(e.title)}</span></div>${e.location?`<div class="small">⌖ ${escapeText(e.location)}</div>`:''}${e.priorityItemId?`<button class="agenda-remove" onclick="event.stopPropagation();removePrioritySchedule('${e.priorityItemId}')">Remove</button>`:''}</div>`).join('');const suggestionHtml=suggestions.map(x=>`<div class="agenda-row suggested"><div><b>${formatClock(x.slot.start)}–${formatClock(x.slot.end)}</b><span>${escapeText(x.entry.title)}</span></div><div class="small">Suggested free time · ${x.entry.estimatedMinutes} min</div><button class="mini-action" onclick="acceptSuggestedSlot('${x.entry.id}','${x.slot.start.toISOString()}')">Accept</button></div>`).join('');box.innerHTML=eventHtml+suggestionHtml||'<div class="empty-state compact">No event or available focus suggestion today.</div>'}
function upcomingGroup(entry){const date=safeTime(entry.dueAt||entry.startAt);if(!date)return null;const diff=Math.round((startOfDay(date)-startOfDay(nowDate()))/DAY);if(diff===1)return 'Tomorrow';if(diff>=2&&diff<=3)return 'Next 3 days';if(diff>=4&&diff<=7)return 'Later this week';return null}
function renderUpcoming(active,focus){const box=document.getElementById('dashboardUpcoming');if(!box)return;const focusIds=new Set(focus.map(x=>x.id)),groups={'Tomorrow':[],'Next 3 days':[],'Later this week':[]};active.forEach(x=>{const g=upcomingGroup(x);if(g&&!focusIds.has(x.id))groups[g].push(x)});box.innerHTML=Object.entries(groups).filter(([,list])=>list.length).map(([name,list])=>`<div class="upcoming-group"><b>${name}</b>${list.slice(0,4).map(x=>`<button onclick="openPrioritySource('${x.id}')"><span>${x.icon}</span><span>${escapeText(x.title)}</span><small>${escapeText(formatDayTime(x.dueAt||x.startAt))}</small></button>`).join('')}</div>`).join('')||'<div class="empty-state compact">No additional dated item in the next 7 days.</div>'}
function renderCompleted(){const box=document.getElementById('dashboardCompleted');if(!box)return;const today=dateKey(nowDate()),items=collectPriorityItems().map(x=>({...x,control:controlFor(x.id)})).filter(x=>x.control.completedAt&&x.control.completedAt!=='source'&&dateKey(new Date(x.control.completedAt))===today).slice(-6).reverse();box.innerHTML=items.length?items.map(x=>`<div class="completed-row"><span>✓</span><div><b>${escapeText(x.title)}</b><small>${escapeText(x.typeLabel)}</small></div><button onclick="undoPriorityItem('${x.id}')">Undo</button></div>`).join(''):'<div class="empty-state compact">Completed items will appear here today.</div>';const count=document.getElementById('dashboardCompletedCount');if(count)count.textContent=`${items.length} completed`}
function prioritySectionData(active,focus){const focusIds=new Set(focus.map(x=>x.id)),upcoming=active.filter(x=>upcomingGroup(x)&&!focusIds.has(x.id)),today=dateKey(nowDate()),completed=collectPriorityItems().map(x=>({...x,control:controlFor(x.id)})).filter(x=>x.control.completedAt&&x.control.completedAt!=='source'&&dateKey(new Date(x.control.completedAt))===today).slice(-10).reverse();return {upcoming,completed}}
function renderPriorityFooter(active,focus){const box=document.getElementById('dashboardPriorityFooter');if(!box)return;const {upcoming,completed}=prioritySectionData(active,focus);box.innerHTML=`<button onclick="openPrioritySection('upcoming')"><span>Upcoming</span><b>${upcoming.length}</b></button><button onclick="openPrioritySection('completed')"><span>Completed today</span><b>${completed.length}</b></button><button onclick="openAllPriorities()"><span>All priorities</span><b>→</b></button>`}
openPrioritySection=function(kind){const active=evaluatedItems(),focus=active.slice(0,5),data=prioritySectionData(active,focus);if(kind==='completed'){openModal(`<h2>Completed today</h2>${data.completed.length?data.completed.map(x=>`<div class="completed-row"><span>✓</span><div><b>${escapeText(x.title)}</b><small>${escapeText(x.typeLabel)}</small></div><button onclick="undoPriorityItem('${x.id}');closeModal()">Undo</button></div>`).join(''):'<div class="empty-state compact">Nothing has been completed today yet.</div>'}`);return}openModal(`<h2>Upcoming · next 7 days</h2>${data.upcoming.length?data.upcoming.map(x=>`<div class="all-priority-row"><span>${x.icon}</span><div><b>${escapeText(x.title)}</b><div class="small">${escapeText(formatDayTime(x.dueAt||x.startAt))} · ${escapeText(x.courseCode||x.typeLabel)}</div></div><span class="priority-level level-${priorityLabel(x.score).toLowerCase()}">${priorityLabel(x.score)}</span><button class="btn ghost" onclick="openPrioritySource('${x.id}')">Open</button></div>`).join(''):'<div class="empty-state compact">No additional dated item in the next 7 days.</div>'}`)};
function renderDynamicDashboard(){const active=evaluatedItems(),focus=active.slice(0,5);applyDashboardLayout();renderDynamicFocus(focus);renderStats(active);renderImportantMails();renderAgenda(active);renderUpcoming(active,focus);renderCompleted();renderPriorityFooter(active,focus);const date=document.getElementById('topDate');if(date)date.textContent=nowDate().toLocaleDateString([], {weekday:'short',day:'numeric',month:'short',year:'numeric'})}

const legacyRenderDashboard=renderDashboard;
renderDashboard=function(){legacyRenderDashboard();renderDynamicDashboard();renderDeadlineStrip()};
saveWorkspaceState=function(){return persist(true)};
function syncCompletion(entry,complete){
  const control=controlFor(entry.id);
  if(entry.sourceType==='assignment'){if(String(entry.sourceId).startsWith('custom:')){const state=workspaceState.customAssignments.find(x=>x.id===String(entry.sourceId).slice(7));if(state)state.done=complete}else{const state=workspaceState.assignments[entry.sourceId];if(state){if(complete)control.previousSourceState=[...state.tasks];state.tasks=complete?state.tasks.map(()=>true):(control.previousSourceState||state.tasks.map(()=>false))}}}
  else if(entry.sourceType==='generated'){const state=(workspaceState.generatedAssignments||[]).find(x=>x.id===entry.sourceId);if(state){if(complete)control.previousSourceState=[...(state.done||[])];state.done=complete?state.tasks.map(()=>true):(control.previousSourceState||state.tasks.map(()=>false))}}
  else if(entry.sourceType==='paper'){const p=workspaceState.papers.find(x=>x.id===entry.sourceId);if(p){if(complete)control.previousSourceState=p.status;p.status=complete?'Completed':(control.previousSourceState||'Queued')}}
  else if(entry.sourceType==='personal'){const task=(workspaceState.miscTasks||[]).find(x=>x.id===entry.sourceId);if(task)task.done=complete}
  else if(entry.sourceType==='lecture'){workspaceState.lectureReviewStatus=workspaceState.lectureReviewStatus||{};workspaceState.lectureReviewStatus[entry.courseCode]=workspaceState.lectureReviewStatus[entry.courseCode]||[];workspaceState.lectureReviewStatus[entry.courseCode][Number(entry.sourceId)]=complete}
  else if(entry.sourceType==='reading'){const reads=workspaceState.courseReading[entry.courseCode]||[];reads[Number(entry.sourceId)]=complete;workspaceState.courseReading[entry.courseCode]=reads}
}
completePriorityItem=function(id,complete=true){const entry=itemById(id);if(!entry||!entry.canComplete)return;const state=controlFor(id);syncCompletion(entry,complete);state.completedAt=complete?new Date().toISOString():null;state.status=complete?'completed':'active';state.updatedAt=new Date().toISOString();persist();renderAssignments();renderPapers();toast(complete?'Completed and synchronized with its source':'Item restored')};
undoPriorityItem=function(id){completePriorityItem(id,false)};
togglePriorityPin=function(id){const s=controlFor(id);s.pinned=!s.pinned;s.updatedAt=new Date().toISOString();persist();toast(s.pinned?'Pinned to your priorities':'Priority unpinned')};
changePriorityLevel=function(id,value){const s=controlFor(id);if(value==='waiting'){s.status='waiting';s.manualPriority='auto'}else{s.status='active';s.manualPriority=['high','medium','low'].includes(value)?value:'auto'}s.updatedAt=new Date().toISOString();persist();toast('Priority updated')};
dismissPriorityItem=function(id){const s=controlFor(id);s.dismissedAt=new Date().toISOString();s.updatedAt=new Date().toISOString();persist();toast('Hidden from Dashboard; source data was not deleted')};
restorePriorityItem=function(id){const s=controlFor(id);s.dismissedAt=null;s.snoozeUntil=null;s.status='active';s.updatedAt=new Date().toISOString();persist();openAllPriorities();toast('Item restored')};
openPrioritySnooze=function(id){const entry=itemById(id);if(!entry)return;const now=nowDate(),later=new Date(now);later.setHours(Math.min(23,now.getHours()+3),0,0,0);const tomorrow=addDays(startOfDay(now),1);tomorrow.setHours(9,0);const week=addDays(startOfDay(now),7);week.setHours(9,0);openModal(`<h2>Snooze · ${escapeText(entry.title)}</h2><p class="small">The source stays unchanged. This item returns automatically when snooze ends.</p><div class="snooze-grid"><button class="btn ghost" onclick="setPrioritySnooze('${id}','${later.toISOString()}')">Later today<br><small>${formatClock(later)}</small></button><button class="btn ghost" onclick="setPrioritySnooze('${id}','${tomorrow.toISOString()}')">Tomorrow<br><small>09:00</small></button><button class="btn ghost" onclick="setPrioritySnooze('${id}','${week.toISOString()}')">Next week<br><small>${week.toLocaleDateString()}</small></button></div><div class="field"><label>Custom date and time</label><input class="form-input" id="prioritySnoozeCustom" type="datetime-local" min="${localInputValue(now)}"></div><button class="btn" onclick="setCustomPrioritySnooze('${id}')">Snooze until custom time</button>`)};
setPrioritySnooze=function(id,value){const date=safeTime(value);if(!date||date<=nowDate()){toast('Choose a future snooze time.');return}const s=controlFor(id);s.snoozeUntil=date.toISOString();s.updatedAt=new Date().toISOString();closeModal();persist();toast(`Snoozed until ${formatDayTime(date)}`)};
setCustomPrioritySnooze=function(id){setPrioritySnooze(id,document.getElementById('prioritySnoozeCustom')?.value)};
openPrioritySource=function(id){const entry=itemById(id);if(!entry){toast('The source item no longer exists.');refreshDashboardPriorities();return}if(entry.sourceType==='mail')return selectImportantMail(Number(entry.sourceId));if(entry.sourceType==='assignment')return String(entry.sourceId).startsWith('custom:')?openCustomAssignment(String(entry.sourceId).slice(7)):openAssignment(entry.sourceId);if(entry.sourceType==='generated')return openGeneratedAssignment(entry.sourceId);if(entry.sourceType==='paper')return openPaper(entry.sourceId);if(entry.sourceType==='calendar')return openEvent(entry.sourceId);if(entry.sourceType==='personal'){go('assignments');return}if(['lecture','reminder','requirement'].includes(entry.sourceType)){if(typeof openLectureStudyPack==='function'&&workspaceState.lectureInsights?.[entry.courseCode]?.[Number(entry.sourceId)])return openLectureStudyPack(entry.courseCode,Number(entry.sourceId));return openCourse(entry.courseCode,'lectures')}if(entry.sourceType==='reading')return openCourse(entry.courseCode,'readings')};
function hasConflict(start,end,ignoreId=null){return busyIntervals(start).some(x=>x.event.id!==ignoreId&&start<x.end&&end>x.start)}
schedulePriorityItem=function(id){const entry=itemById(id);if(!entry)return;const existing=(workspaceState.events||[]).find(e=>e.priorityItemId===id),slot=existing?{start:parseDateTime(existing.date,existing.time),end:parseDateTime(existing.date,existing.end)}:findSlot(entry);openModal(`<h2>${existing?'Edit':'Schedule'} focus time</h2><p><b>${escapeText(entry.title)}</b></p>${slot?`<div class="course-note">Suggested free time: <b>${escapeText(formatDayTime(slot.start))}–${escapeText(formatClock(slot.end))}</b></div>`:'<div class="analysis-state error">No available time today</div>'}<div class="field"><label>Start</label><input class="form-input" id="priorityScheduleStart" type="datetime-local" value="${slot?localInputValue(slot.start):''}"></div><div class="field"><label>Duration</label><select class="form-select" id="priorityScheduleDuration">${[15,30,45,60,90,120].map(n=>`<option value="${n}" ${n===entry.estimatedMinutes?'selected':''}>${n} minutes</option>`).join('')}</select></div><button class="btn" onclick="savePrioritySchedule('${id}')">${existing?'Update':'Add to My Day'}</button>${existing?` <button class="btn ghost danger-text" onclick="removePrioritySchedule('${id}')">Remove</button>`:''}`)};
savePrioritySchedule=function(id){const entry=itemById(id),start=safeTime(document.getElementById('priorityScheduleStart')?.value),duration=Number(document.getElementById('priorityScheduleDuration')?.value)||30;if(!entry||!start){toast('Choose a valid start time.');return}const end=new Date(start.getTime()+duration*MINUTE),existing=(workspaceState.events||[]).find(e=>e.priorityItemId===id);if(hasConflict(start,end,existing?.id)){toast('That time overlaps a fixed event. Choose another time.');return}const record={id:existing?.id||`focus-${hash(id)}`,date:dateKey(start),time:formatClock(start),end:formatClock(end),title:`Focus · ${entry.title}`,module:'Focus',priorityItemId:id,recurring:false};if(existing)Object.assign(existing,record);else workspaceState.events.push(record);controlFor(id).scheduledEventId=record.id;controlFor(id).updatedAt=new Date().toISOString();closeModal();persist();renderCalendar();toast('Focus time added without moving fixed events')};
acceptSuggestedSlot=function(id,startValue){const entry=itemById(id),start=safeTime(startValue);if(!entry||!start)return;const end=new Date(start.getTime()+entry.estimatedMinutes*MINUTE);if(hasConflict(start,end)){toast('That free time is no longer available.');renderDashboard();return}const existing=(workspaceState.events||[]).find(e=>e.priorityItemId===id);const record={id:existing?.id||`focus-${hash(id)}`,date:dateKey(start),time:formatClock(start),end:formatClock(end),title:`Focus · ${entry.title}`,module:'Focus',priorityItemId:id,recurring:false};if(existing)Object.assign(existing,record);else workspaceState.events.push(record);controlFor(id).scheduledEventId=record.id;persist();renderCalendar();toast('Suggested time accepted')};
removePrioritySchedule=function(id){workspaceState.events=(workspaceState.events||[]).filter(e=>e.priorityItemId!==id);controlFor(id).scheduledEventId=null;closeModal();persist();renderCalendar();toast('Focus time removed; the task remains active')};
openDashboardSchedule=function(){const active=evaluatedItems().filter(x=>x.canComplete).slice(0,6);openModal(`<h2>Plan focus time</h2><p class="small">Suggestions use today’s free time and never move fixed classes or Calendar events.</p>${active.length?active.map(x=>{const slot=findSlot(x);return `<div class="paper-row file-row"><div><b>${escapeText(x.title)}</b><div class="small">${slot?`${formatClock(slot.start)}–${formatClock(slot.end)} available`:'No available time today'}</div></div>${slot?`<button class="btn ghost" onclick="acceptSuggestedSlot('${x.id}','${slot.start.toISOString()}')">Accept</button>`:`<button class="btn ghost" onclick="schedulePriorityItem('${x.id}')">Choose another day</button>`}</div>`}).join(''):'<div class="empty-state">No active item needs scheduling.</div>'}`)};
openAllPriorities=function(){const all=evaluatedItems({includeHidden:true}),now=nowDate();const rows=all.filter(x=>!x.expired).map(x=>{const hidden=x.dismissedAt||(x.snoozeUntil&&safeTime(x.snoozeUntil)>now),completed=x.sourceCompleted||x.completedAt;return `<div class="all-priority-row"><span class="priority-source-icon">${x.icon}</span><div><b>${escapeText(x.title)}</b><div class="small">${escapeText(metaLine(x))} · ${escapeText(x.reason||'Not currently ranked')}</div></div><span class="priority-level level-${priorityLabel(x.score).toLowerCase()}">${x.score}</span><button class="btn ghost" onclick="openPrioritySource('${x.id}')">Open</button>${hidden&&!completed?`<button class="btn ghost" onclick="restorePriorityItem('${x.id}')">Restore</button>`:''}</div>`}).join('');openModal(`<h2>All workspace priorities</h2><div class="course-note"><b>Local rules, not cloud AI</b><br><span class="small">Scores use deadlines, Calendar timing, Gmail labels, course type and your Pin or manual priority choices.</span></div>${rows||'<div class="empty-state">No source-backed workspace items are available.</div>'}`)};
refreshDashboardPriorities=function(){const ids=new Set(collectPriorityItems().map(x=>x.id));Object.keys(priorityState.itemState).forEach(id=>{if(!ids.has(id))delete priorityState.itemState[id]});workspaceState.events=(workspaceState.events||[]).filter(e=>!e.priorityItemId||ids.has(e.priorityItemId));persist();toast('Priorities recalculated from current workspace data')};

const legacyRenderAssignments=renderAssignments;
renderAssignments=function(){legacyRenderAssignments();const box=document.getElementById('customAssignmentList');if(!box)return;box.innerHTML=workspaceState.customAssignments.length?workspaceState.customAssignments.map(a=>`<div class="card"><span class="badge ${a.done?'good':a.priority==='high'?'danger':'warn'}">${a.done?'Completed':escapeText(relativeTime(a.dueAt))}</span><h3>${escapeText(a.course&&a.course!=='Personal'?a.course+' · ':'')}${escapeText(a.title)}</h3><p class="small">${escapeText(a.description||'User-created assignment')} · ${a.estimatedMinutes||60} min</p><button class="btn" onclick="openCustomAssignment('${a.id}')">Open</button> <button class="btn ghost danger-text" onclick="deleteCustomAssignment('${a.id}')">Delete</button></div>`).join(''):''};
function reflectSourceCompletion(id,complete){const state=controlFor(id);state.completedAt=complete?(state.completedAt||new Date().toISOString()):null;state.status=complete?'completed':'active';state.updatedAt=new Date().toISOString();persist()}
const legacyToggleAssignmentTask=toggleAssignmentTask;
toggleAssignmentTask=function(id,index,value){legacyToggleAssignmentTask(id,index,value);const a=workspaceState.assignments[id];reflectSourceCompletion(`assignment:${id}`,Boolean(a?.tasks?.length&&a.tasks.every(Boolean)))};
const legacyToggleGeneratedAssignmentTask=toggleGeneratedAssignmentTask;
toggleGeneratedAssignmentTask=function(id,index,value){legacyToggleGeneratedAssignmentTask(id,index,value);const a=workspaceState.generatedAssignments.find(x=>x.id===id);reflectSourceCompletion(`generated:${id}`,Boolean(a?.tasks?.length&&a.tasks.every((_,i)=>a.done?.[i])))};
const legacyToggleMiscTask=toggleMiscTask;
toggleMiscTask=function(index,value){const task=workspaceState.miscTasks[index];legacyToggleMiscTask(index,value);if(task?.id)reflectSourceCompletion(`personal:${task.id}`,Boolean(value))};
const legacyToggleCourseReading=toggleCourseReading;
toggleCourseReading=function(code,index,value){const titles=[...(courseCatalog[code]?.readings||[]),...(workspaceState.readingUploads?.[code]||[]).map(x=>x.title)],title=titles[index]||String(index);legacyToggleCourseReading(code,index,value);reflectSourceCompletion(`reading:${code}:${index}:${hash(title)}`,Boolean(value))};
const legacyUpdatePaper=updatePaper;
updatePaper=function(id,key,value){legacyUpdatePaper(id,key,value);if(key==='status')reflectSourceCompletion(`paper:${id}`,value==='Completed')};
openNewAssignment=function(){const tomorrow=addDays(startOfDay(nowDate()),1);tomorrow.setHours(23,59);openModal(`<h2>New assignment</h2><div class="field"><label>Title</label><input class="form-input" id="newAssignmentTitle" placeholder="Assignment title"></div><div class="grid2"><div class="field"><label>Course</label><select class="form-select" id="newAssignmentCourse">${[...Object.keys(courseCatalog),'Personal'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Due date and time</label><input class="form-input" id="newAssignmentDue" type="datetime-local" value="${localInputValue(tomorrow)}"></div></div><div class="grid2"><div class="field"><label>Estimated time</label><select class="form-select" id="newAssignmentEstimate">${[30,45,60,90,120,180].map(n=>`<option value="${n}" ${n===60?'selected':''}>${n} minutes</option>`).join('')}</select></div><div class="field"><label>Priority</label><select class="form-select" id="newAssignmentPriority"><option value="high">High</option><option value="normal">Auto</option><option value="low">Low</option></select></div></div><div class="field"><label>Description</label><textarea id="newAssignmentDescription" placeholder="Requirements, deliverables or next step"></textarea></div><button class="btn" onclick="saveNewAssignment()">Create assignment</button>`)};
saveNewAssignment=function(){const title=clean(document.getElementById('newAssignmentTitle')?.value),course=document.getElementById('newAssignmentCourse')?.value||'Personal',due=safeTime(document.getElementById('newAssignmentDue')?.value),estimatedMinutes=Number(document.getElementById('newAssignmentEstimate')?.value)||60,priority=document.getElementById('newAssignmentPriority')?.value||'high',description=clean(document.getElementById('newAssignmentDescription')?.value);if(!title){toast('Enter an assignment title.');return}workspaceState.customAssignments.push({id:`custom-assignment-${Date.now()}-${hash(title)}`,title,course,dueAt:due?.toISOString()||null,estimatedMinutes,priority,description,done:false,createdAt:new Date().toISOString()});closeModal();persist();renderAssignments();toast('Assignment created and added to dynamic priorities')};
openCustomAssignment=function(id){const a=workspaceState.customAssignments.find(x=>x.id===id);if(!a)return;openModal(`<h2>${escapeText(a.course&&a.course!=='Personal'?a.course+' · ':'')}${escapeText(a.title)}</h2><span class="badge ${a.done?'good':a.priority==='high'?'danger':'warn'}">${a.done?'Completed':escapeText(relativeTime(a.dueAt))}</span><div class="course-note"><b>Due</b><br>${escapeText(formatDayTime(a.dueAt))} · ${a.estimatedMinutes||60} minutes</div><div class="ai-summary">${escapeText(a.description||'No requirements have been added yet.')}</div><label class="check-row ${a.done?'done':''}"><input type="checkbox" ${a.done?'checked':''} onchange="completePriorityItem('assignment:custom:${a.id}',this.checked)"><span>Mark this assignment complete</span></label><div class="settings-actions"><button class="btn ghost" onclick="schedulePriorityItem('assignment:custom:${a.id}')">Schedule</button><button class="btn ghost danger-text" onclick="deleteCustomAssignment('${a.id}')">Delete</button></div>`)};
deleteCustomAssignment=function(id){if(!confirm('Delete this assignment?'))return;workspaceState.customAssignments=workspaceState.customAssignments.filter(x=>x.id!==id);closeModal();refreshDashboardPriorities();renderAssignments();toast('Assignment deleted')};

openQuickTask=function(){const tomorrow=addDays(startOfDay(nowDate()),1);tomorrow.setHours(18,0);openModal(`<h2>Add task</h2><div class="field"><label>Task</label><input class="form-input" id="quickTaskTitle" placeholder="What needs to be done?"></div><div class="grid2"><div class="field"><label>Due date and time</label><input class="form-input" id="quickTaskDue" type="datetime-local" value="${localInputValue(tomorrow)}"></div><div class="field"><label>Estimated time</label><select class="form-select" id="quickTaskEstimate">${[15,30,45,60,90,120].map(n=>`<option value="${n}" ${n===30?'selected':''}>${n} minutes</option>`).join('')}</select></div></div><div class="field"><label>Priority</label><select class="form-select" id="quickTaskPriority"><option value="normal">Auto</option><option value="high">High</option><option value="low">Low</option></select></div><button class="btn" onclick="saveQuickTask()">Add task</button>`)};
saveQuickTask=function(){const title=clean(document.getElementById('quickTaskTitle')?.value),due=safeTime(document.getElementById('quickTaskDue')?.value),estimatedMinutes=Number(document.getElementById('quickTaskEstimate')?.value)||30,priority=document.getElementById('quickTaskPriority')?.value||'normal';if(!title){toast('Enter a task title.');return}workspaceState.miscTasks.push({id:`task-${Date.now()}-${hash(title)}`,title,done:false,dueAt:due?.toISOString()||null,estimatedMinutes,priority,createdAt:new Date().toISOString()});closeModal();persist();renderAssignments();toast('Task added to dynamic priorities')};
createMailTask=function(index){const mail=mails[index],id=`mail-task-${hash(mail.url||mail.title)}`;if(!(workspaceState.miscTasks||[]).some(t=>t.id===id||t.title===mail.title))workspaceState.miscTasks.push({id,title:mail.title,description:mail.action,done:false,estimatedMinutes:15,priority:mail.priority==='High'?'high':'normal',sourceMailIndex:index,createdAt:new Date().toISOString()});persist();renderAssignments();toast('Mail task added without changing Gmail')};
openTodaySummary=function(){const active=evaluatedItems(),top=active[0],agenda=todayAgenda(active).events;openModal(`<h2>Today at a glance</h2><div class="ai-summary"><b>${active.length} active source-backed item(s)</b><p>${top?`Start with “${escapeText(top.title)}” because ${escapeText(top.reason.toLowerCase())}.`:'No active item needs attention.'}</p></div><div class="paper-row"><b>Today’s fixed and accepted schedule</b><div class="small">${agenda.length?agenda.map(e=>`${formatClock(e.occurrenceStart)} ${escapeText(e.title)}`).join(' · '):'No event scheduled'}</div></div><button class="btn" onclick="closeModal();openDashboardSchedule()">Plan focus time</button>`)};
workspaceAnswer=(function(original){return function(question){if(/今天|today|先做|priority|优先/.test(String(question).toLowerCase())){const top=evaluatedItems().slice(0,3);return top.length?`Your current priorities are ${top.map((x,i)=>`${i+1}. ${x.title} (${x.reason})`).join('；')}. These are calculated from local workspace rules.`:'No active source-backed priority is currently available.'}return original(question)}})(workspaceAnswer);
showGeneratedSummary=(function(original){return function(type){if(type!=='today')return original(type);const active=evaluatedItems(),top=active.slice(0,3),agenda=todayAgenda(active).events;const body=top.length?`You have ${active.length} active source-backed item(s).\n\nStart with:\n${top.map((x,i)=>`${i+1}. ${x.title} — ${x.reason}`).join('\n')}\n\nToday’s fixed or accepted schedule:\n${agenda.length?agenda.map(e=>`${formatClock(e.occurrenceStart)} ${e.title}`).join('\n'):'No event scheduled.'}`:'No active source-backed priority is currently available.';window.lastGeneratedSummary=body;openModal(`<button class="btn ghost" onclick="openSummarize()">← Back</button><h2>Today’s rules-based brief</h2><div class="course-note"><b>Local calculation</b><br><span class="small">This brief uses saved deadlines, Calendar timing and source status. It is not cloud AI interpretation.</span></div><div class="ai-summary" style="white-space:pre-line">${escapeText(body)}</div><button class="btn ghost" onclick="copyGeneratedSummary()">Copy summary</button>`)}})(showGeneratedSummary);
